export interface DebounceOptions {
  /** Invoke on the leading edge of the wait timeout (default: false). */
  leading?: boolean;
  /** Invoke on the trailing edge of the wait timeout (default: true). */
  trailing?: boolean;
  /** Upper bound on how long `fn` may be delayed before being forced to run. */
  maxWait?: number;
}

export interface ThrottleOptions {
  /** Invoke on the leading edge of the throttle window (default: true). */
  leading?: boolean;
  /** Invoke on the trailing edge of the throttle window (default: true). */
  trailing?: boolean;
}

export interface Control {
  cancel(): void;
  flush(): unknown;
}

type AnyFn = (...args: any[]) => any;

interface State {
  timer: ReturnType<typeof setTimeout> | null;
  lastCallTime: number | null;   // when debounced fn was last invoked by caller
  lastInvokeTime: number | null; // when fn actually ran
  pending: boolean;              // an invocation is scheduled
}

function now(): number {
  return Date.now();
}

/**
 * Creates a debounced function that delays invoking `fn` until `wait` ms have
 * elapsed since the last time it was called, subject to `maxWait`.
 *
 * The returned function preserves `this` and the latest arguments, returns the
 * result of the last actual invocation of `fn` (or undefined if none happened),
 * and exposes `cancel()` and `flush()`.
 */
export function debounce<F extends AnyFn>(
  fn: F,
  wait = 0,
  options: DebounceOptions = {},
): F & Control {
  const leading = options.leading === true;
  const trailing = options.trailing !== false;
  const maxWait = typeof options.maxWait === 'number' ? options.maxWait : null;

  let timerId: ReturnType<typeof setTimeout> | null = null;
  let maxTimerId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<F> | null = null;
  let thisArg: unknown = undefined;
  let lastCallTime: number | null = null;   // last call by the consumer
  let lastInvokeTime: number | null = null; // last time fn actually ran
  let result: ReturnType<F> | undefined;

  function invoke(time: number) {
    const args = lastArgs!;
    lastArgs = null;
    lastInvokeTime = time;
    result = fn.apply(thisArg, args);
    return result;
  }

  function remainingWait(time: number): number {
    const sinceLastCall = time - (lastCallTime as number);
    const sinceLastInvoke = time - (lastInvokeTime as number);
    const timeWaiting = wait - sinceLastCall;
    const maxWaitRemaining =
      maxWait === null ? Infinity : maxWait - sinceLastInvoke;
    return Math.min(timeWaiting, maxWaitRemaining);
  }

  function shouldInvoke(time: number): boolean {
    if (lastCallTime === null) return true;
    if (time - lastCallTime >= wait) return true;
    if (
      maxWait !== null &&
      lastInvokeTime !== null &&
      time - lastInvokeTime >= maxWait
    ) {
      return true;
    }
    // Never invoked yet, but a maxWait deadline has already passed.
    if (maxWait !== null && lastInvokeTime === null && time - (lastCallTime as number) >= maxWait) {
      return true;
    }
    return false;
  }

  function timerExpired() {
    const time = now();
    if (shouldInvoke(time)) {
      invoke(time);
      reset();
    } else {
      startTimer(remainingWait(time));
    }
  }

  function startTimer(waitMs: number) {
    clearTimer();
    timerId = setTimeout(timerExpired, Math.max(0, Math.ceil(waitMs)));
  }

  function clearTimers() {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    if (maxTimerId !== null) {
      clearTimeout(maxTimerId);
      maxTimerId = null;
    }
  }

  function reset() {
    clearTimers();
    lastCallTime = null;
    lastInvokeTime = null;
  }

  function debounced(this: unknown, ...args: Parameters<F>): ReturnType<F> | undefined {
    const time = now();
    const isInvoking = shouldInvoke(time);

    lastArgs = args;
    thisArg = this;
    lastCallTime = time;

    if (isInvoking) {
      if (timerId === null) {
        // Start of a new burst.
        lastInvokeTime = leading ? null : time; // anchor for maxWait either way
        if (leading) {
          invoke(time);
          // If only-leading (no trailing), nothing more is scheduled.
          if (!trailing) {
            lastCallTime = time; // keep burst state until next call
            timerId = setTimeout(() => { timerId = null; }, wait);
            return result;
          }
        }
        startTimer(remainingWait(time));
        return result;
      }
      // Mid-burst forced invocation (e.g. maxWait elapsed).
      invoke(time);
      if (trailing && timerId !== null) {
        startTimer(remainingWait(time));
      } else {
        reset();
      }
      return result;
    }

    startTimer(remainingWait(time));
    return result;
  }

  function cancel() {
    if (!pendingState()) return;
    clearTimers();
    lastArgs = null;
    thisArg = undefined;
    lastCallTime = null;
    lastInvokeTime = null;
    result = undefined;
  }

  function pendingState(): boolean {
    return timerId !== null || maxTimerId !== null || lastCallTime !== null;
  }

  function flush(): ReturnType<F> | undefined {
    if (timerId === null && lastArgs === null) return result;
    cancel();
    if (lastArgs === null) return result;
    const args = lastArgs;
    const ctx = thisArg;
    lastArgs = null;
    result = fn.apply(ctx, args);
    return result;
  }

  return Object.assign(debounced, { cancel, flush }) as F & Control;
}

/**
 * Creates a throttled function that invokes `fn` at most once every `wait` ms.
 * By default it fires on the leading edge and again on the trailing edge of
 * the window with the latest arguments.
 */
export function throttle<F extends AnyFn>(
  fn: F,
  wait = 0,
  options: ThrottleOptions = {},
): F & Control {
  const leading = options.leading !== false;
  const trailing = options.trailing !== false;

  const debounced = debounce(function (this: unknown, ...args: Parameters<F>) {
    // A throttled invocation never re-arms another timeout beyond the window:
    // we run exactly one leading and/or one trailing fire per window.
    return fn.apply(this, args);
  }, wait, { leading, trailing });

  // Throttle semantics: after the first (leading or deferred) fire within a
  // window, further calls inside that window must not extend the schedule —
  // they only update args. We implement this directly rather than via plain
  // debounce, so build it explicitly here instead.
  void debounced;

  let timerId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<F> | null = null;
  let thisArg: unknown = undefined;
  let lastFireTime: number | null = null; // actual fire time (null = never fired)
  let result: ReturnType<F> | undefined;

  function fire() {
    const args = lastArgs!;
    lastArgs = null;
    lastFireTime = now();
    result = fn.apply(thisArg, args);
  }

  function remaining(): number {
    return wait - (now() - (lastFireTime as number));
  }

  function throttled(this: unknown, ...args: Parameters<F>): ReturnType<F> | undefined {
    lastArgs = args;
    thisArg = this;
    const time = now();

    if (lastFireTime === null) {
      // First-ever call.
      if (leading) {
        fire();
        timerId = setTimeout(onWindowEnd, wait);
        return result;
      }
      timerId = setTimeout(fireTrailing, wait);
      return result;
    }

    const rem = remaining();
    if (rem <= 0) {
      // Window has fully elapsed: this call starts a new window.
      if (timerId !== null) {
        // Trailing fire was scheduled but its window already expired without
        // firing (possible when timers are advanced past it); treat as fresh.
        clearTimeout(timerId);
        timerId = null;
      }
      if (leading) {
        fire();
        timerId = setTimeout(onWindowEnd, wait);
      } else {
        timerId = setTimeout(fireTrailing, wait);
      }
      return result;
    }

    // Inside an active window: just record latest args. If no trailing fire is
    // scheduled yet (window started but trailing disabled... n/a) do nothing.
    if (trailing && timerId === null) {
      timerId = setTimeout(fireTrailing, rem);
    }
    return result;
  }

  function fireTrailing() {
    timerId = null;
    if (lastArgs === null) return;
    fire();
    // Arm a fresh window so subsequent calls respect spacing from this fire.
    timerId = setTimeout(onWindowEnd, wait);
  }

  function onWindowEnd() {
    timerId = null;
    // Window closed; if args arrived during the window they were handled by
    // the trailing timer. Nothing else to do — next call starts a new window.
  }

  function cancel() {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    lastArgs = null;
    thisArg = undefined;
    lastFireTime = null;
    result = undefined;
  }

  function flush(): ReturnType<F> | undefined {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    if (lastArgs === null) return result;
    fire();
    return result;
  }

  return Object.assign(throttled, { cancel, flush }) as F & Control;
}

