    const args = pendingArgs as Parameters<F>;
    const ctx = pendingThis;
    pendingArgs = null;
    slotTime = now();
    result = fn.apply(ctx, args);
  }

  function onTimer() {
    timerId = null;
    if (!trailing || pendingArgs === null) return;
    fire();
  }

  function throttled(this: unknown, ...args: Parameters<F>) {
    const t = now();
    pendingArgs = args;
    pendingThis = this;

    if (slotTime === null) {
      slotTime = t;
      if (leading) {
        fire();
      }
      if (trailing) arm(t);
      return result;
    }

    if (timerId !== null) {
      // inside reserved window; args recorded
      return result;
    }

    const elapsed = t - slotTime;
    if (elapsed >= wait) {
      slotTime = t;
      if (leading) fire();
      if (trailing) arm(t);
      return result;
