    // returned early without arming, or leading fired with trailing disabled)
    if (trailing) arm(slotTime);
    return result;
  }

  function arm(from: number) {
    clearTimer();
    timerId = setTimeout(onTimer, Math.max(0, from + wait - now()));
  }
