export interface DebounceOptions {
  /** Invoke on the leading edge of the wait timeout (default: false). */
  leading?: boolean;
  /** Invoke on the trailing edge of the wait timeout (default: true). */
  trailing?: boolean;
  /** Upper bound on how long `fn` may be delayed before being forced to run. */
  maxWait?: number;
}

export interface ThrottleOptions {
  /** Invoke on the leading edge of the throttle window (default: true). */
  leading?: boolean;
  /** Invoke on the trailing edge of the throttle window (default: true). */
  trailing?: boolean;
}

export interface Control<R = unknown> {
  /** Drop any pending invocation. */
  cancel(): void;
  /** Run a pending invocation immediately; returns its result (or the last result). */
  flush(): R | undefined;
}

type AnyFn = (...args: any[]) => any;

function now(): number {
  return Date.now();
}

/**
 * Debounce: delays invoking `fn` until `wait` ms have elapsed since the last
 * call, capped by `options.maxWait`. Preserves `this` and the latest
 * arguments, returns the last actual invocation result, and exposes
 * `cancel()` / `flush()`.
 */
export function debounce<F extends AnyFn>(
  fn: F,
  wait = 0,
  options: DebounceOptions = {},
): ((...args: Parameters<F>) => ReturnType<F>) & Control<ReturnType<F>> {
  const leading = options.leading === true;
  const trailing = options.trailing !== false;
  const maxWait =
    typeof options.maxWait === "number" ? options.maxWait : null;

  let timerId: ReturnType<typeof setTimeout> | null = null;
  let pendingArgs: Parameters<F> | null = null;
  let pendingThis: unknown;
  let lastCallTime: number | null = null; // last debounced() call
  let lastInvokeTime: number | null = null; // last real execution in this burst
  let burstStart: number | null = null; // when the current burst began
  let result: ReturnType<F> | undefined;

  function clearTimer(): void {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
  }

  function invokeNow(): ReturnType<F> {
    const args = pendingArgs as Parameters<F>;
    const ctx = pendingThis;
    pendingArgs = null;
    lastInvokeTime = now();
    result = fn.apply(ctx, args);
    return result;
  }

  function finishCycle(): void {
    clearTimer();
    pendingArgs = null;
    pendingThis = undefined;
    lastCallTime = null;
    lastInvokeTime = null;
    burstStart = null;
  }

  function forcedDue(): number {
    // maxWait deadline is anchored to the burst (first call) or last execution.
    const anchor = lastInvokeTime ?? burstStart as number;
    return maxWait === null ? Infinity : anchor + maxWait;
  }

  function armTimer(): void {
    const t = now();
    const due = Math.min((lastCallTime as number) + wait, forcedDue());
    clearTimer();
    timerId = setTimeout(onExpire, Math.max(0, due - t));
  }

  function onExpire(): void {
    timerId = null;
    const t = now();
    if (pendingArgs === null) {
      finishCycle();
      return;
    }
    const ready = t >= (lastCallTime as number) + wait || t >= forcedDue();
    if (ready) {
      invokeNow();
      finishCycle();
    } else {
      armTimer(); // quiet period not yet reached; reschedule
    }
  }

  function debounced(
    this: unknown,
    ...args: Parameters<F>
  ): ReturnType<F> | undefined {
    const t = now();
    const wasIdle = timerId === null && burstStart === null;
    pendingArgs = args;
    pendingThis = this;
    lastCallTime = t;

    if (wasIdle) {
      burstStart = t;
      lastInvokeTime = null;
      if (leading) {
        invokeNow();
        if (!trailing) {
          finishCycle(); // leading-only: each call stands alone
          return result;
        }
        armTimer(); // trailing catch-up armed from this invoke
        return result;
      }
      armTimer();
      return result;
    }

    // Active burst: record args; make sure a timer is outstanding.
    if (timerId === null) {
      armTimer();
    }
    return result;
  }

  function cancel(): void {
    finishCycle();
  }

  function flush(): ReturnType<F> | undefined {
    clearTimer();
    if (pendingArgs === null) return result;
    invokeNow();
