import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { debounce, throttle } from "../src/index.js";

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
});

describe("debounce", () => {
  it("invokes once on the trailing edge by default, with the latest args and result", () => {
    const fn = vi.fn((x: number) => x * 2);
    const d = debounce(fn, 100);

    expect(d(1)).toBeUndefined(); // nothing invoked yet -> no result
    vi.advanceTimersByTime(50);
    d(2);
    vi.advanceTimersByTime(49);
    expect(fn).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1); // t = 100ms since last call
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith(2);

    // returns the last invocation result
    expect(d(3)).toBe(4);
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(2);
    expect(fn).toHaveBeenLastCalledWith(3);
  });

  it("fires on both leading and trailing edges when leading: true", () => {
    const fn = vi.fn((s: string) => s.toUpperCase());
    const d = debounce(fn, 100, { leading: true });

    d("a");
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith("a");

    d("b");
    vi.advanceTimersByTime(50);
    d("c");
    vi.advanceTimersByTime(49);
    expect(fn).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(1); // trailing edge at t=100
    expect(fn).toHaveBeenCalledTimes(2);
    expect(fn).toHaveBeenLastCalledWith("c");

    // burst is over: the next call leads again immediately
    vi.advanceTimersByTime(200);
    d("x");
    expect(fn).toHaveBeenCalledTimes(3);
    expect(fn).toHaveBeenLastCalledWith("x");
  });

  it("preserves `this`", () => {
    interface Ctx { id: number }
    const ctx: Ctx = { id: 7 };
    const fn = vi.fn(function (this: Ctx, x: number) {
      return this.id + x;
    });
    const d = debounce(fn, 50, { leading: true });
    expect(d.call(ctx, 1)).toBe(8);
    expect(fn.mock.instances[0]).toBe(ctx);

    // and on the trailing edge
    const d2 = debounce(fn, 50);
    let captured: unknown;
    fn.mockImplementationOnce(function (this: Ctx) {
      captured = this;
      return 0;
    });
    d2.call(ctx, 9);
    vi.advanceTimersByTime(50);
    expect(captured).toBe(ctx);
  });

  it("maxWait forces an invoke mid-burst even while calls keep arriving", () => {
    const fn = vi.fn((s: string) => s);
    const d = debounce(fn, 100, { maxWait: 250 });

    d("a"); // t=0
    vi.advanceTimersByTime(60);
    d("b"); // t=60
    vi.advanceTimersByTime(60);
    d("c"); // t=120
    vi.advanceTimersByTime(60);
    d("e"); // t=180
    vi.advanceTimersByTime(60);
    d("f"); // t=240

    expect(fn).not.toHaveBeenCalled(); // wait keeps pushing the edge out...

    vi.advanceTimersByTime(9); // t=249 — still under the cap
    expect(fn).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1); // t=250 — maxWait deadline hit
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith("f");

    // burst consumed; a quiet period produces no extra calls
    vi.advanceTimersByTime(500);
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it("cancel() prevents a pending call and allows reuse afterwards", () => {
    const fn = vi.fn();
    const d = debounce(fn, 100);

    d("z");
    expect(fn).not.toHaveBeenCalled();
    d.cancel();

    vi.advanceTimersByTime(1000);
    expect(fn).not.toHaveBeenCalled();

    // reusable after cancel
    d("y");
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith("y");
  });

  it("flush() invokes a pending call immediately with latest args and this", () => {
    interface Ctx { tag: string }
    const ctx: Ctx = { tag: "ctx" };
    const fn = vi.fn(function (this: Ctx | undefined, s: string) {
      return `${this?.tag ?? ""}:${s}`;
    });
    const d = debounce(fn, 100);

    d.call(ctx, "q");
    expect(fn).not.toHaveBeenCalled();

    const r = d.flush();
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith("q");
    expect(fn.mock.instances[0]).toBe(ctx);
    expect(r).toBe("ctx:q");

    // flush with nothing pending returns the last result without re-running
    expect(d.flush()).toBe("ctx:q");
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it("cancel() after flush does not double-invoke", () => {
    const fn = vi.fn();
    const d = debounce(fn, 100);
    d("once");
    d.flush();
    d.cancel();
    vi.advanceTimersByTime(500);
    expect(fn).toHaveBeenCalledTimes(1);
  });
});

describe("throttle", () => {
  it("fires immediately (leading) and once more on the trailing edge with latest args", () => {
    const fn = vi.fn((n: number) => n);
    const t = throttle(fn, 100);

    t(1);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith(1);

    t(2);
    vi.advanceTimersByTime(40);
    t(3);
    expect(fn).toHaveBeenCalledTimes(1); // inside window: swallowed

    vi.advanceTimersByTime(60); // t=100: trailing fire
    expect(fn).toHaveBeenCalledTimes(2);
    expect(fn).toHaveBeenLastCalledWith(3);

    vi.advanceTimersByTime(200);
    t(4);
    expect(fn).toHaveBeenCalledTimes(3); // new window leads again
    expect(fn).toHaveBeenLastCalledWith(4);
  });

  it("trailing-only mode defers the first call to the window edge", () => {
    const fn = vi.fn();
    const t = throttle(fn, 100, { leading: false });

    t("a");
    expect(fn).not.toHaveBeenCalled();
    vi.advanceTimersByTime(100);
    expect(fn).toHaveBeenCalledTimes(1);
    expect(fn).toHaveBeenCalledWith("a");
  });

  it("supports cancel() and flush()", () => {
    const fn = vi.fn((n: number) => n * 10);
    const t = throttle(fn, 100);

    t(5);
    t(6); // queued for trailing edge
    expect(fn).toHaveBeenCalledTimes(1);

    expect(t.flush()).toBe(60); // pending args executed now
    expect(fn).toHaveBeenCalledTimes(2);
    expect(fn).toHaveBeenLastCalledWith(6);

    t(7);
    t.cancel();
    vi.advanceTimersByTime(1000);
    expect(fn).toHaveBeenCalledTimes(2); // cancelled trailing fire never ran
  });
});

